     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  value: Expression;
    67→}
    68→
    69→/**
    70→ * 표현식 문장
    71→ */
    72→export interface ExprStatement extends ASTNode {
    73→  type: 'ExprStatement';
    74→  expression: Expression;
    75→}
    76→
    77→/**
    78→ * If 문장
    79→ */
    80→export interface IfStatement extends ASTNode {
    81→  type: 'IfStatement';
    82→  condition: Expression;
    83→  thenBranch: Statement[];
    84→  elseBranch?: Statement[];
    85→}
    86→
    87→/**
    88→ * While 루프
    89→ */
    90→export interface WhileStatement extends ASTNode {
    91→  type: 'WhileStatement';
    92→  condition: Expression;
    93→  body: Statement[];
    94→}
    95→
    96→/**
    97→ * 문장 타입 (Return, Assign, ExprStatement, IfStatement, WhileStatement)
    98→ */
    99→export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement | WhileStatement;
   100→
   101→/**
   102→ * 숫자 리터럴
   103→ */
   104→export interface NumberLiteral extends ASTNode {
   105→  type: 'Number';
   106→  value: number | string; // 16진수, 이진수 표현 가능
   107→}
   108→
   109→/**
   110→ * 문자열 리터럴
   111→ */
   112→export interface StringLiteral extends ASTNode {
   113→  type: 'String';
   114→  value: string;
   115→}
   116→
   117→/**
   118→ * 식별자 (변수명, 함수명 등)
   119→ */
   120→export interface Identifier extends ASTNode {
   121→  type: 'Identifier';
   122→  name: string;
   123→}
   124→
   125→/**
   126→ * 이항 연산식
   127→ * 예: x + y, a * b
   128→ */
   129→export interface BinaryExpr extends ASTNode {
   130→  type: 'BinaryExpr';
   131→  left: Expression;
   132→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   133→  right: Expression;
   134→}
   135→
   136→/**
   137→ * 함수 호출 표현식
   138→ * 예: foo(), Module::func()
   139→ */
   140→export interface CallExpr extends ASTNode {
   141→  type: 'Call';
   142→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   143→  args: Expression[];
   144→}
   145→
   146→/**
   147→ * 배열 리터럴
   148→ * 예: [1, 2, 3], []
   149→ */
   150→export interface ArrayLiteral extends ASTNode {
   151→  type: 'Array';
   152→  elements: Expression[];
   153→}
   154→
   155→/**
   156→ * 배열 접근
   157→ * 예: arr[0], items[i]
   158→ */
   159→export interface ArrayAccess extends ASTNode {
   160→  type: 'ArrayAccess';
   161→  object: Expression;
   162→  index: Expression;
   163→}
   164→
   165→/**
   166→ * 멤버 접근
   167→ * 예: arr.length, obj.property
   168→ */
   169→export interface MemberAccess extends ASTNode {
   170→  type: 'MemberAccess';
   171→  object: Expression;
   172→  property: string;
   173→}
   174→
   175→/**
   176→ * 표현식 타입
   177→ */
   178→export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr | ArrayLiteral | ArrayAccess | MemberAccess;
   179→
   180→/**
   181→ * 프로그램 (최상위 노드)
   182→ */
   183→export interface Program {
   184→  type: 'Program';
   185→  body: Array<VFunction | PyFunction | Statement>;
   186→}
